INSERT INTO [social].[OfficialAnnouncements] ([Id], [Title], [Summary], [Content], [Category], [Status], [PublishAt], [EndAt], [CreatedByUserId], [CreatedAt], [UpdatedAt]) VALUES
    ('b3ec86dc-d61d-5e66-9174-9ce12c72a4da', N'文物明信片展示資料更新', N'本次展示資料已同步 512 件文物與對應商品。', N'本次展示資料已同步圖鑑、題庫、文物明信片與會員操作範例，詳細數量與版本請以目前有效的資料庫 Snapshot 為準。', N'UPDATE', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-16T12:19:13.6610000', 126), CONVERT(datetime2(3), '2026-10-19T12:19:13.6610000', 126), '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-16T12:19:13.6610000', 126), CONVERT(datetime2(3), '2026-09-16T12:19:13.6610000', 126));
INSERT INTO [social].[SocialComments] ([Id], [PostId], [ParentCommentId], [UserId], [Content], [Status], [CreatedAt], [UpdatedAt], [SimHash], [AiReviewedAt]) VALUES
    ('f35df9b8-2851-2758-a59f-000fc471438f', 'e3179cdf-eb1f-af50-8dde-d371e9e7eb89', '6b09a231-b07b-8d5f-951a-4bfeb4033117', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'盤內那枚看不清的朱印先標成未辨識比較妥，模糊處不能硬讀成答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-03T09:54:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('c8de76cc-38b8-b552-8ee9-0034f91538ab', '908f40ce-b5a7-b153-9b9f-d6f7ecbd5739', 'f25e4c59-7c2b-8f50-ac2b-76782c0ea852', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-21T08:41:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('a8c2cda6-fa37-235e-8312-0049f9945bdb', 'c9eacb60-647d-165d-a650-f15ba568c1da', '98a1046d-93fe-ff59-a770-db77382442f5', '59538e0b-3f85-46d0-93d6-cccb9df12831', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-05T00:44:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('51d6c03f-e602-d354-809e-00fe8088156a', 'da294627-14d1-7952-8da9-8ddc278a69de', 'b4f5a07a-648e-145e-aea3-39fe2d97c257', '7881ef5d-547d-4d08-b71d-a48be2000a35', N'把圖鑑連結和小禮物一起送很貼心，朋友想追作品的來源時也不會只剩一張圖。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-20T03:04:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('e9da6296-c8ed-9b56-a03c-019555c54128', '958c8440-1396-2f55-a591-2b2320924f6f', NULL, '2d049534-161d-4862-971f-e410d2ac9162', N'你把文物明信片很短，但剛好提醒我回到圖鑑繼續看寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-07T08:26:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('3985fb6e-07c7-bd5c-a0d5-02634ccf609d', '0e94d2cc-7e36-2053-8cd9-999e278026fb', NULL, 'f43ee0b6-a28d-47c1-a5e2-32fa9060383c', N'介紹作品時把不確定處說清楚很重要，讀者才分得出觀察和推測。之後補上來源，也能保留理解改變的過程。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-14T00:43:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('ccd91e9a-89eb-c255-8cdf-029d3731bb3c', 'd77ed3d0-ec84-1158-891a-04a0838c9c2e', 'd858cbfe-83dc-d254-9b50-8577977e588c', 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'同一個紋樣能被看出不同意思很正常，先各自指出位置再聊，比急著選答案更有趣。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-08T11:49:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('b03d6dbc-5a61-df5e-84f6-032dde3d202e', 'ac06a04a-27a8-d85d-9d5c-d8f0f01a6e25', '004799e8-365b-6050-a693-1aa4eaad87c7', 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'原本的參觀清單先留著很實際，下次改期就不用從交通和想看的作品重新查起。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-24T09:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('06ef8b2c-b4ae-265f-b20b-0367e5ff4eb4', 'cb31c93c-8d6c-2757-a688-5ed1e297af34', '12c8b08f-2134-5559-a7a2-244b965f0c37', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-13T09:42:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('2dec4c7e-9c5c-4eb7-a977-03d38c03f1e4', 'da40fd33-e4cd-697e-e12e-4e574343afe0', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'很有參考價值，下次展覽我也想去看看。', N'PUBLISHED', CONVERT(datetime2(3), '2026-10-06T07:23:32.2030000', 126), CONVERT(datetime2(3), '2026-10-06T07:23:32.2030000', 126), 7952206830877953619, CONVERT(datetime2(3), '2026-10-06T07:23:32.2030000', 126)),
    ('ede01536-b2de-2d50-928b-048b8f0dfffb', 'ef0513a5-ea0f-d955-9d79-9474b8b79367', 'b7f53adb-d0a6-585f-b23e-946df5523ac3', 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'如果之後有地圖選點，我會希望文字地址仍然保留，這樣在不同裝置或地圖載入較慢時也能看懂集合位置。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-31T10:34:00.0000000', 126), CONVERT(datetime2(3), '2025-10-31T10:34:00.0000000', 126), NULL, NULL),
    ('2ac0b4cf-47b5-6755-af14-048c3e157933', '96690504-0727-675d-a2e0-ee0c0abc7495', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'你把文物明信片最適合放在我每天會讀資料的地方寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-14T07:49:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('3f442e2b-21a5-5652-9787-04ae29539f29', '17327017-40a5-a95d-902d-9fae2b56af51', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'提示先讓人看清輪廓，再補比較方向，猜測才有地方落腳。這篇把作答順序說得很實際。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-16T08:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('9b9a21a5-801f-e358-ab62-04edc1cbaf80', 'ea125a61-0806-bd56-8278-38b022b8d139', NULL, '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'你把我現在會把遊戲結果當成回到圖鑑的入口，而不是最後答案寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-18T11:30:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('a0bf2bad-043b-3c53-a955-04fa14c44b4a', 'fb85df44-71ce-3358-8c5c-70653b6443b9', NULL, 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-03T02:57:00.0000000', 126), CONVERT(datetime2(3), '2026-05-03T02:57:00.0000000', 126), NULL, NULL),
    ('7f58e262-3683-be54-8fd4-05209f907218', 'a78da64f-2d0b-8e53-97a1-639da38f320a', NULL, '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-22T04:36:00.0000000', 126), CONVERT(datetime2(3), '2026-03-22T04:36:00.0000000', 126), NULL, NULL),
    ('88d379ad-afa3-d353-ac3e-06491d604a16', '6e4bd3ab-6e5f-5b5c-974e-fde14ecd9735', NULL, 'a1c4407f-acee-4abe-a702-e164fb399b2e', N'我剛好在另一件相近作品上遇到類似情況，表面看起來很像，但器底與尺寸比例其實差不少。這篇提供了一個很好的比較起點。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-13T02:27:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('47a4a511-1468-6851-8494-06b053cd9093', '94d48c6b-46b3-fc5f-9ff1-e1475252c442', '08a5f65c-da0a-4d51-a863-89cf443a4c72', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'若是第一次到場，我還會先確認入口、樓層和報到方式；這些細節不一定適合塞進標題，但對真正要參加的人很重要。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-28T07:14:00.0000000', 126), CONVERT(datetime2(3), '2025-10-28T07:14:00.0000000', 126), NULL, NULL),
    ('c1d25c12-a260-d250-92ce-06c07265ed4f', '26ea876d-b1ed-e85a-b8e6-9d269cb40a58', '1520019b-dbef-c458-9df2-44914bee3b1f', 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-03T02:35:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('301d9124-79eb-df5f-b3d9-06c4f3992dcb', 'f6c34f0d-5545-6751-a235-22c138d3c113', '6152758b-2285-1a5d-959b-c11c7b6e150c', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'揭曉後再回圖鑑對照，確實比只記得答對答錯更容易看出漏了哪個線索。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-17T11:00:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('95a3b2c5-41d1-e058-9503-07cc761e887a', '19852cde-895c-c65d-9d74-0215c96c67b2', '37602ab5-13de-a85a-a365-87e5a6647a4c', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-18T07:05:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('95705dd4-f275-385d-a062-082835037adb', '0abb32d3-a338-7153-87f3-efcc1b15db73', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'你把不是每次看展都要拍照，有時候只坐著記一個視線落點寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-24T07:38:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('99e30063-5bf5-255e-bc29-0858a01c8927', '93eb8a2b-b90c-a25a-91c8-7efdfccea368', NULL, '32090e80-8d61-4801-b480-a6358f7a9e37', N'你把我沒有把這篇心得寫成答案，因為還有一段資料需要確認寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-05T05:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('4d73efb3-ee04-7a5f-a242-08a9e83402a7', 'a516868f-b544-b95f-a620-a14626870609', NULL, '4134ddc4-ca89-4180-ac72-bbe0f42ab285', N'我也會先看大觀通寶的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-29T00:25:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('f6a037f1-38c3-1c52-aad4-08c6824859fe', '035c641c-6eb0-8d58-a828-bf1a8f28a540', NULL, '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'你把我用三個欄位比較作品，不再用一個很像就結束寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-04T05:24:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('f07f937a-51dc-b455-ab48-091d78c7079c', '2391f330-6ee0-3e5b-872d-653180ed3782', 'f375326d-856f-b75b-9205-a4eeaddba3e5', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-30T08:42:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('f9e4cef6-93f7-4b5a-9d86-0979b5804305', 'a331b6d4-cc7e-2b5d-abdb-5a26bd4f1775', NULL, '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'我也會先看掐絲琺瑯夔龍紋簋式爐的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-12T08:46:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('ab6676c4-66e5-065f-ae9f-09c6cf638999', 'a78da64f-2d0b-8e53-97a1-639da38f320a', '7f58e262-3683-be54-8fd4-05209f907218', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'讀完公告後，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-22T04:45:00.0000000', 126), CONVERT(datetime2(3), '2026-03-22T04:45:00.0000000', 126), NULL, NULL),
    ('de3df396-7e0a-439d-b227-0aebcd24f10a', 'e3ebcd5b-8037-4824-a827-d1cc5841c62c', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'很有參考價值，下次展覽我也想去看看。', N'PUBLISHED', CONVERT(datetime2(3), '2026-10-06T08:25:33.1450000', 126), CONVERT(datetime2(3), '2026-10-06T08:25:33.1450000', 126), 7952206830877953619, CONVERT(datetime2(3), '2026-10-06T08:25:33.1450000', 126)),
    ('43c6b6aa-8064-2058-a563-0b1663a74148', 'ac484caf-fd99-f95a-b7d5-aa0929a466f7', '0252595b-ba06-b950-a660-8bfbad75657d', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'讀完公告後，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-12T09:38:00.0000000', 126), CONVERT(datetime2(3), '2026-04-12T09:38:00.0000000', 126), NULL, NULL),
    ('89f01341-d3e9-f65f-ba24-0b41d68ce24c', 'a875e167-b5b9-c459-a152-65e82d465121', '391c2288-64f1-bf56-8a03-d60a565512a7', 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-21T10:33:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('1c6b9347-a661-d859-adc2-0b942ddbd62a', '8a2d16b2-c536-175b-9d83-6e13919d3f1a', NULL, '5d5ef6cb-7ee7-4ed0-ad20-7b42e666af70', N'你把如果作品只有一個角度的圖，大家會先怎麼避免過度解讀寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-05T05:36:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('4698a813-1c5a-a858-96e8-0c86800206ea', '5d2e7ea7-c9be-be5b-8399-12fe3fd31a5d', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-04T09:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('77344c03-8150-6058-81a6-0cda5a415cca', '9e49ba45-d0fd-0c55-a3f0-7706dc2f8e3d', '412bbcdd-6f84-2e54-b816-3c79dcce8a02', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-14T10:44:00.0000000', 126), CONVERT(datetime2(3), '2026-04-14T10:44:00.0000000', 126), NULL, NULL),
    ('45321f41-7e18-2e53-9f59-0cf7544193cf', 'd0f8799f-9cd6-ab5e-a0c1-11edbd57f145', '88210352-0ca5-1652-a6c9-29a044872398', '59538e0b-3f85-46d0-93d6-cccb9df12831', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-18T10:15:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('2990da4f-7fb5-1d5d-98e1-0d0ece2b248f', '47966729-b0f2-c95d-9a6f-2413f53842c8', NULL, '7881ef5d-547d-4d08-b71d-a48be2000a35', N'讀完後我會想再找不同角度的影像來對照。掐絲琺瑯鼎這類作品如果只看縮圖，真的很容易漏掉邊緣與接合處的線索。', N'HIDDEN', CONVERT(datetime2(3), '2026-02-10T07:56:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('10125f6f-ef33-d555-8ff3-0d20541de964', '0a530476-33c3-0255-85d3-d726a414e1d7', NULL, '2d049534-161d-4862-971f-e410d2ac9162', N'你把陪長輩看展時，我們從生活用途開始聊比較自然寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-13T11:29:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('7289fdfc-91fc-305c-867f-0d4e9be119d6', 'ee2b1f16-3d7d-4e57-9dde-81d9b0c17564', NULL, 'f43ee0b6-a28d-47c1-a5e2-32fa9060383c', N'提示先讓人看清輪廓，再補比較方向，猜測才有地方落腳。這篇把作答順序說得很實際。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-18T04:55:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('d9496e81-c0d0-d650-9df6-0dfdce232c7f', '53ac137e-5e54-d55e-b3d7-93593a7094a7', NULL, 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-26T05:54:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('2a9aa2e5-6b78-c858-be43-0e7fbd727f9e', '6110e474-c87e-d353-9a3e-5f48621ae8bc', 'fcf90586-b36f-bc5d-9085-3d9dcf5d6e3e', 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-10T11:07:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('b4dc8806-d811-8355-abd8-0e85c73c953d', '00d36a2a-039f-ea5d-9de0-896df2a75b43', '180677ce-cc6a-1f5c-89b7-ff425b9400a7', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-10T01:08:00.0000000', 126), CONVERT(datetime2(3), '2025-11-10T01:08:00.0000000', 126), NULL, NULL),
    ('e78942fa-f486-f253-8cc6-0e94700dc103', 'd235b0f5-b447-9f5e-9a23-10b5a7b6e3c9', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'活動資訊整理得很完整，先看到時間與地點，再回到活動頁確認名額和報名狀態，參加前比較不容易漏掉重要條件。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-08T09:24:00.0000000', 126), CONVERT(datetime2(3), '2025-11-08T09:24:00.0000000', 126), NULL, NULL),
    ('75510d95-1bdf-645d-abdd-0eac436ded70', 'ca37bab4-09c3-f859-b2e5-ca7579b80093', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'兩個器口並排後，弧度差異確實更容易看出來。比起先猜年代，我會先把這個形狀記下來。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-05T07:36:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('0aea5fc5-0de5-5550-bc72-0eb4d647d513', '7ecaf2c0-5ed4-4354-a7e1-691cb80d7ffa', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'你把如果要去南院參加活動，我會把集合位置先記成文字寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-16T10:39:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('f020f348-024c-395b-8c99-0fed1e4adcf1', '3c55a2f5-2496-c85d-a942-7d37701ce229', NULL, '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'讀完後我會想再找不同角度的影像來對照。剔紅八寶番蓮紋燭台這類作品如果只看縮圖，真的很容易漏掉邊緣與接合處的線索。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-02T11:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('85727443-c740-d958-a029-0ff7c531ee02', '42b8ac79-4156-055f-9310-8e2e63ce8a43', '977881b5-733e-7557-bd69-6a3b6751a1bc', 'a1c4407f-acee-4abe-a702-e164fb399b2e', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-29T00:46:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('dfd76b37-db64-c05e-bf81-107bc916d406', '4954163f-6ba6-745b-81dd-d6dfc64f27de', NULL, 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-23T01:50:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('923b6700-7704-9e5a-99a8-10a62f5f4a32', '178f5461-211c-bb57-8cec-de3143601048', '72d9aadf-a300-6b5e-8fdf-262ab42abfdf', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'先把操作和時間說清楚，新手才能把心力留給看線索，不必猜流程。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-05T05:53:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('8cd32187-5c0f-4256-a700-10f29a798ab4', '21d7be2a-4a81-265a-b6d7-9682411f71b8', '2d8d17ec-ddf3-d555-9cd4-f20fb7f08904', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'你提到掐絲琺瑯雙耳鳳瓶時沒有只留一句好看，而是把觀看的條件和自己的想法說出來，這樣比較容易一起核對。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-22T04:53:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('1cad355b-d508-105d-be65-111df37a76a5', '2ceb079e-c635-795e-9936-e8ddf550dff0', 'e8f5ba4c-2d44-5656-bd7d-2ee44d7fe230', '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-08T02:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('e0926425-98e5-da50-89fb-119e44db7f3d', '7d09817b-6f46-0d53-87d8-ca866a3bc7f8', NULL, '32090e80-8d61-4801-b480-a6358f7a9e37', N'器形、尺寸和影像角度都要一起看，單靠醒目顏色真的很容易走偏。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-11T01:52:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('41e50664-42bd-b257-893f-122e889a49bd', '11e0df85-fa91-f950-909a-06fc245383b7', '5fde3bdd-5f36-2755-abed-ebe72ba0da15', '4134ddc4-ca89-4180-ac72-bbe0f42ab285', N'同一張圖有人先看輪廓、有人先讀文字很正常，理由講清楚就能互相補線索。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-24T07:55:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('316e2c4a-0d44-4b5e-8e97-125d8e306a0e', '9bd92ca6-1126-2a5e-9822-d1e3ca15a846', NULL, '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-02T01:39:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('22b5d577-9d6f-f753-895f-12fb41975ffa', 'dc987966-47e3-4d52-ad70-78767115ad54', 'eae03bf1-603a-b754-a39b-e5a3383e3eba', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'你提到日本 江戶時代 十七世紀或更晚 銅鎏金女神立像時沒有只留一句好看，而是把觀看的條件和自己的想法說出來，這樣比較容易一起核對。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-01T11:48:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('8d43bb4a-3856-5650-8b53-12fb727349ef', '65fdb4c2-a385-735e-b2e8-cc255a8372f6', 'd170dd93-a5d3-ac54-b87c-4184eee149e0', '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'補充一個小想法：如果之後加入更多照片，可以把拍攝角度和光線條件一起記下來，會更方便比較。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-31T03:48:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('8a96b5c2-2afd-ff59-8139-135ea6426721', '0b8cbd64-b4c4-755b-9cfb-7c383075db8c', '99b05ee2-06ff-4455-bb29-d2f93bb099bc', 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'讀完公告後，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-21T00:53:00.0000000', 126), CONVERT(datetime2(3), '2026-02-21T00:53:00.0000000', 126), NULL, NULL),
    ('e5e91e51-4401-43f0-a544-1387551cc2c0', 'da40fd33-e4cd-697e-e12e-4e574343afe0', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'很有參考價值，下次展覽我也想去看看。', N'PUBLISHED', CONVERT(datetime2(3), '2026-10-06T07:23:30.6110000', 126), CONVERT(datetime2(3), '2026-10-06T07:23:30.6110000', 126), 7952206830877953619, CONVERT(datetime2(3), '2026-10-06T07:23:30.6110000', 126)),
    ('4bd5bc8d-646b-4857-85ca-14eaa4b0189b', '8adbfa68-6c2a-8b55-9609-913a69871c22', '07a7acf4-de5b-e552-a449-b79d265227fd', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'讀完公告後，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-19T01:04:00.0000000', 126), CONVERT(datetime2(3), '2026-05-19T01:04:00.0000000', 126), NULL, NULL),
    ('02156e5a-1bfe-1e54-8126-15151f3b990a', '17327017-40a5-a95d-902d-9fae2b56af51', '3f442e2b-21a5-5652-9787-04ae29539f29', 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'提示先讓人看清輪廓，再補比較方向，猜測才有地方落腳。這篇把作答順序說得很實際。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-16T08:56:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('dd1e4caf-58db-417b-8e61-154dbf2fffeb', '073c01a2-fe46-4205-972b-b02523ed147c', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'這個觀察也提醒我不要只依賴單一欄位。年代、分類與來源彼此可以互相校對，但任何一項都不應該脫離完整資料單獨決定答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T01:56:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126), NULL, NULL),
    ('cacabcb2-3185-2c57-9ce4-155b88def16d', '024a6fc7-817f-8757-b67e-010526132f0e', 'e752bacd-485e-5f51-aecc-43e6eb19a96f', '5d5ef6cb-7ee7-4ed0-ad20-7b42e666af70', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-24T05:51:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('5100121b-3918-e25c-b0b7-1567a7f33bd7', '43492eba-a671-a550-b712-d4e4d34546c5', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'你把遊戲中的錯誤答案，也可以變成下一次看展的提醒寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-21T03:45:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('c98ad510-9f45-2b51-b422-1694944e9058', 'd1b55ecf-c105-f35d-9991-ae616dc52945', NULL, '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-31T05:31:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('151dffa8-5e56-db58-a564-16c0b0d5acdf', 'e6e6e595-e0f1-ce51-840d-a87897dc75fa', NULL, '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-25T08:40:00.0000000', 126), CONVERT(datetime2(3), '2026-03-25T08:40:00.0000000', 126), NULL, NULL),
    ('bea5fc83-9e28-215b-ac78-171bead65234', '6ecae0c1-296e-cb58-b721-429c4ffc8ad9', '0135cb91-e2b3-fa57-97e8-4355321bf9b5', '59538e0b-3f85-46d0-93d6-cccb9df12831', N'我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-09T03:50:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('cf751430-dee1-a557-9521-176cc0775225', 'c0062988-e07c-085a-b33f-8dc9862bb279', '85c1c42f-7273-1d5e-9288-83ad571f8979', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'讀完公告後，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-14T05:46:00.0000000', 126), CONVERT(datetime2(3), '2026-03-14T05:46:00.0000000', 126), NULL, NULL),
    ('29dd34d8-82a9-3256-8c2d-18101fb6881e', 'f0414220-6159-6b5f-9052-2da6e09541c3', NULL, 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-07T02:34:00.0000000', 126), CONVERT(datetime2(3), '2026-04-07T02:34:00.0000000', 126), NULL, NULL),
    ('84cc18a1-1b26-255c-8a49-1867f4f6e9da', 'eab2d40a-bef9-1f55-859a-07aa6af2ba6e', NULL, '7881ef5d-547d-4d08-b71d-a48be2000a35', N'我也會先看剔彩雲龍紋圓盒的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-09T04:42:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('63567ba4-1399-4f55-a7a7-18bb1bb3a227', '4e3ae402-37d3-e856-b2d5-c5dd6c5de95d', NULL, '2d049534-161d-4862-971f-e410d2ac9162', N'你把兩件作品名稱很像，我先從編號而不是印象開始對照寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-03T07:47:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('77bea40a-1a8f-6259-867b-196c4cf7dbbb', '7b3e8167-2d4c-4e52-aba5-47aa295bd7fe', '07a040be-c52d-b056-990e-8d6d93bcb050', '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'這種原則也能幫忙檢查展示資料是否過度延伸；看起來豐富的內容，仍然要讓人知道哪些是原始記錄、哪些是社群整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-06T06:44:00.0000000', 126), CONVERT(datetime2(3), '2026-05-06T06:44:00.0000000', 126), NULL, NULL),
    ('d07c4c57-8465-a450-ac57-19a6c3294837', '6f9a89c7-16b8-e355-9b20-97d94f7be8ec', 'be1d6e24-a6df-d153-be2e-8ea252e3e5aa', 'f43ee0b6-a28d-47c1-a5e2-32fa9060383c', N'低圈足和盤身比例值得先記下，這回我也差點只看花形就急著猜用途。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-19T00:37:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1620000', 126), NULL, NULL),
    ('03010f6b-003a-e951-87df-19dff40a63b9', '63cf5b9a-7ff0-1757-8400-8f9bb4584cbd', '055269e2-9ebf-f956-91d4-d7e094a85ddf', 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-19T05:39:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('adbe9f02-5dc0-8856-83db-1a2e07c25fe4', 'b3ac41b8-9d74-4d55-94bf-6f77bb6a12df', NULL, 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'你把玉器穿孔的位置，讓我開始想像它原本怎麼被拿取寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-17T09:49:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('004799e8-365b-6050-a693-1aa4eaad87c7', 'ac06a04a-27a8-d85d-9d5c-d8f0f01a6e25', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'你把活動取消後我沒有刪掉原本的參觀計畫寫成具體的觀看經過，而不是只留下好不好看的結論；我也遇過類似情況，最有用的是把當時的角度和後來查到的資料一起留下。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-24T09:38:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('77960346-9993-1853-8692-1aac5fe866b6', '3e85d9bc-6a68-6c5e-8ab8-2420f0e3c3e1', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'我也會先看剔紅三獅戲球紋長方匣的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-06T04:53:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('6bfd4e56-f0eb-4d57-8b43-1aae52c8a3f3', 'd3cb2942-33f1-af54-ad8c-314dc4674018', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'我剛好在另一件相近作品上遇到類似情況，表面看起來很像，但器底與尺寸比例其實差不少。這篇提供了一個很好的比較起點。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-17T02:39:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('025cffe0-9ae9-5d58-9625-1ac023ffd7c7', '908c07c9-16c0-af5e-a4a3-fcf988c76f13', '88407342-6b67-2857-91a7-4dcfd134f5d2', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'補充一個小想法：如果之後加入更多照片，可以把拍攝角度和光線條件一起記下來，會更方便比較。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-06T11:33:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('1c1ee174-def3-695e-8ce0-1aefa21e16f8', 'f0b00e71-833e-ff56-b438-a05919e020a7', NULL, 'a1c4407f-acee-4abe-a702-e164fb399b2e', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-22T09:34:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
    ('e0c2aa81-4736-825d-84b9-1b7e2b80f2a6', '52eaa6f7-d47f-c454-ad8c-e7eccd00cd11', '9367867d-7073-745a-aeed-1b9a36ccd930', 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'你提到元管道昇竹溪攬勝　軸時沒有只留一句好看，而是把觀看的條件和自己的想法說出來，這樣比較容易一起核對。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-09T01:03:00.0000000', 126), CONVERT(datetime2(3), '2026-10-02T11:21:42.1510000', 126), NULL, NULL),
