INSERT INTO [store].[ProductReviews] ([Id], [ProductId], [UserId], [Rating], [Content], [Status], [CreatedAt], [UpdatedAt]) VALUES
    ('ffe855db-cad2-4e5e-8688-01507e0f27dc', '16bacd38-b166-cea5-efa7-c15456459b3b', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', 4, N'我把青花五彩花卉紋十方蓋碗－複製品＆文物明信片套組和青花五彩花卉紋十方蓋碗的圖鑑頁放在一起看，先確認名稱與影像，再安排展示位置；商品是回到原作的入口，不是原作本身。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-19T03:00:00.0000000', 126), CONVERT(datetime2(3), '2026-01-19T03:45:00.0000000', 126)),
